import {bool, rule, when} from 'gdp-wired'

export const meterRule = rule("Meter")
  .inputs({enabled: bool})
  .state({n: 0})
  .step(({enabled, n}) => ({n: when(enabled, 0, n)}))

// What every state of the code is: a law about every state is about the code's with these beside it.
export const meterInvariants = [meterRule.law("n within its type's range", ({n}) => n.atMost(2147483647))]
